on conflict (option_id, locale) do nothing;

-- producer_translation.description
with v(pl, locale, tr) as (values ('Amerykański producent telewizorów i wyświetlaczy zewnętrznych odpornych na warunki atmosferyczne. Partner resellerski ModularHub Europe.', 'en', 'American manufacturer of weather resistant outdoor TVs and displays. Reseller partner of ModularHub Europe.'),
  ('Amerykański producent telewizorów i wyświetlaczy zewnętrznych odpornych na warunki atmosferyczne. Partner resellerski ModularHub Europe.', 'de', 'US-amerikanischer Hersteller von wetterfesten Outdoor-Fernsehern und -Displays. Reseller-Partner von ModularHub Europe.'),
  ('Amerykański producent telewizorów i wyświetlaczy zewnętrznych odpornych na warunki atmosferyczne. Partner resellerski ModularHub Europe.', 'nl', 'Amerikaanse fabrikant van weerbestendige buitentelevisies en -displays. Reseller-partner van ModularHub Europe.'),
  ('Polski producent domów modułowych, obecny na rynku od 7 lat, z 30 zrealizowanymi projektami. Konstrukcja spawana ze stali, docieplenie PUR/styropian, elewacja z fasady strukturalnej. Domy budowane również w standardzie KfW-Effizienzhaus 40/40 Plus. Kontakt: kontakt@perfectcube.eu, www.perfectcube.eu.', 'en', 'Polish manufacturer of modular homes, on the market for 7 years with 30 completed projects. Welded steel structure, PUR/polystyrene insulation, structural façade cladding. Homes are also built to the KfW Effizienzhaus 40/40 Plus standard.'),
  ('Polski producent domów modułowych, obecny na rynku od 7 lat, z 30 zrealizowanymi projektami. Konstrukcja spawana ze stali, docieplenie PUR/styropian, elewacja z fasady strukturalnej. Domy budowane również w standardzie KfW-Effizienzhaus 40/40 Plus. Kontakt: kontakt@perfectcube.eu, www.perfectcube.eu.', 'de', 'Polnischer Hersteller von Modulhäusern, seit 7 Jahren am Markt, mit 30 realisierten Projekten. Geschweißte Stahlkonstruktion, Dämmung aus PUR/Polystyrol, Fassade mit Strukturverkleidung. Die Häuser werden auch im Standard KfW-Effizienzhaus 40/40 Plus gebaut.'),
  ('Polski producent domów modułowych, obecny na rynku od 7 lat, z 30 zrealizowanymi projektami. Konstrukcja spawana ze stali, docieplenie PUR/styropian, elewacja z fasady strukturalnej. Domy budowane również w standardzie KfW-Effizienzhaus 40/40 Plus. Kontakt: kontakt@perfectcube.eu, www.perfectcube.eu.', 'nl', 'Poolse fabrikant van modulaire woningen, al 7 jaar actief op de markt, met 30 gerealiseerde projecten. Gelaste staalconstructie, isolatie van PUR/polystyreen, gevel met structuurbekleding. De woningen worden ook gebouwd volgens de KfW-Effizienzhaus 40/40 Plus-standaard.'),
  ('Polski producent saun zewnętrznych (m.in. model Qube), dostawa gotowa do użycia; fundament i przyłącze elektryczne po stronie klienta.', 'en', 'Polish manufacturer of outdoor saunas (including the Qube model), delivered ready to use; foundation and electrical connection are the customer''s responsibility.'),
  ('Polski producent saun zewnętrznych (m.in. model Qube), dostawa gotowa do użycia; fundament i przyłącze elektryczne po stronie klienta.', 'de', 'Polnischer Hersteller von Außensaunen (u. a. Modell Qube), Lieferung gebrauchsfertig; Fundament und Stromanschluss erfolgen durch den Kunden.'),
  ('Polski producent saun zewnętrznych (m.in. model Qube), dostawa gotowa do użycia; fundament i przyłącze elektryczne po stronie klienta.', 'nl', 'Poolse fabrikant van buitensauna''s (o.a. model Qube), gebruiksklaar geleverd; fundering en elektrische aansluiting zijn voor rekening van de klant.'),
  ('Polski producent saun zewnętrznych (m.in. model Relax 550), łącznie z montażem; piec, kolor impregnacji drewna i panele podczerwieni dobierane osobno jako płatne opcje.', 'en', 'Polish manufacturer of outdoor saunas (including the Relax 550 model), installation included; the stove, wood stain colour and infrared panels are chosen separately as paid options.'),
  ('Polski producent saun zewnętrznych (m.in. model Relax 550), łącznie z montażem; piec, kolor impregnacji drewna i panele podczerwieni dobierane osobno jako płatne opcje.', 'de', 'Polnischer Hersteller von Außensaunen (u. a. Modell Relax 550), einschließlich Montage; Ofen, Farbton der Holzimprägnierung und Infrarotpaneele werden separat als kostenpflichtige Optionen gewählt.'),
  ('Polski producent saun zewnętrznych (m.in. model Relax 550), łącznie z montażem; piec, kolor impregnacji drewna i panele podczerwieni dobierane osobno jako płatne opcje.', 'nl', 'Poolse fabrikant van buitensauna''s (o.a. model Relax 550), inclusief montage; kachel, kleur van de houtimpregnatie en infraroodpanelen worden apart gekozen als betaalde opties.'),
  ('Producent kontenerów i pawilonów modułowych na bazie stalowej konstrukcji, Czekanów.', 'en', 'Manufacturer of modular containers and pavilions on a steel frame, based in Czekanów.'),
  ('Producent kontenerów i pawilonów modułowych na bazie stalowej konstrukcji, Czekanów.', 'de', 'Hersteller von Modulcontainern und -pavillons auf Stahlkonstruktion, Sitz in Czekanów.'),
  ('Producent kontenerów i pawilonów modułowych na bazie stalowej konstrukcji, Czekanów.', 'nl', 'Fabrikant van modulaire containers en paviljoens op een staalconstructie, gevestigd in Czekanów.'))
insert into producer_translation (producer_id, locale, description)
select pr.id, v.locale::product_translation_locale, v.tr from producer pr join v on pr.description = v.pl where pr.deleted_at is null
on conflict (producer_id, locale) do update set description = excluded.description, updated_at = now() where coalesce(btrim(producer_translation.description), '') = '';

