insert into product_translation (product_id, locale, foundation_options)
select p.id, v.locale::product_translation_locale, v.tr from product p join v on p.foundation_options = v.pl where p.deleted_at is null
on conflict (product_id, locale) do update set foundation_options = excluded.foundation_options, updated_at = now() where coalesce(btrim(product_translation.foundation_options), '') = '';

